export function luhnDigit(body: string): string {
    let s = 0;
    let double = true;
    for (let i = body.length - 1; i >= 0; i--) {
        let d = Number(body[i]);
        if (double) {
            d *= 2;
            if (d > 9) d -= 9;
        }
        s += d;
        double = !double;
    }
    return String((10 - (s % 10)) % 10);
}

export const luhnValid = (s: string): boolean => /^\d{2,}$/.test(s) && luhnDigit(s.slice(0, -1)) === s.slice(-1);

export function gs1Digit(body: string): string {
    let s = 0;
    for (let i = 0; i < body.length; i++) s += Number(body[body.length - 1 - i]) * (i % 2 === 0 ? 3 : 1);
    return String((10 - (s % 10)) % 10);
}

export const gs1Valid = (s: string): boolean => /^\d{8,14}$/.test(s) && gs1Digit(s.slice(0, -1)) === s.slice(-1);

/** The remainder of a long decimal string modulo 97, 7 digits at a time. */
export function mod97(numeric: string): number {
    let r = 0;
    for (let i = 0; i < numeric.length; i += 7) r = Number(String(r) + numeric.slice(i, i + 7)) % 97;
    return r;
}

const ibanNumeric = (s: string): string => [...s].map(c => (/[A-Z]/.test(c) ? String(c.charCodeAt(0) - 55) : c)).join('');

export const IBAN_LENGTHS: Record<string, number> = { FR: 27, DE: 22, GB: 22, ES: 24, IT: 27, NL: 18, BE: 16, PT: 25, CH: 21, AT: 20, LU: 20, IE: 22, PL: 28, SE: 24, DK: 18, NO: 15, FI: 18 };

export function ibanCheck(country: string, bban: string): string {
    return String(98 - mod97(ibanNumeric(bban + country + '00'))).padStart(2, '0');
}

export function ibanValid(s: string): boolean {
    const v = s.replace(/\s+/g, '').toUpperCase();
    if (!/^[A-Z]{2}\d{2}[A-Z0-9]{11,30}$/.test(v)) return false;
    const expected = IBAN_LENGTHS[v.slice(0, 2)];
    if (expected !== undefined && v.length !== expected) return false;
    return mod97(ibanNumeric(v.slice(4) + v.slice(0, 4))) === 1;
}
